function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function renderMarkdown(text) {
  const lines = text.split(/\r?\n/);
  const html = [];
  let listType = null;
  const closeList = () => { if (listType) { html.push(`</${listType}>`); listType = null; } };
  for (const raw of lines) {
    const line = raw.trimEnd();
    const h = /^(#{1,4})\s+(.*)$/.exec(line);
    const ul = /^\s*[-*]\s+(.*)$/.exec(line);
    const ol = /^\s*(\d+)[.)]\s+(.*)$/.exec(line);
    if (h) { closeList(); const lvl = h[1].length; html.push(`<h${lvl+1}>${inline(h[2])}</h${lvl}>`); }
    else if (ul) { if (listType !== 'ul') { closeList(); html.push('<ul>'); listType='ul'; } html.push(`<li>${inline(ul[1])}</li>`); }
    else if (ol) { if (listType !== 'ol') { closeList(); html.push('<ol>'); listType='ol'; } html.push(`<li>${inline(ol[2])}</li>`); }
    else if (line.trim() === '') { closeList(); }
    else { closeList(); html.push(`<p>${inline(line)}</p>`); }
  }
  closeList();
  return html.join('');
}

function inline(s) {
  return escapeHtml(s)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '<em>$1</em>');
}
